oxy_webhelp_navlinks = {"tocId-d39307e15017":{"topics":[{"title":"Editing KMS","shortdesc":"<p class=\"shortdesc\">Edit the KMS credentials to update configuration details for an existing KMS instance         as per the KMS type.<\/p>","href":"saas\/editing_kms.html","attributes":{"data-id":"editing_kms"},"menu":{"hasChildren":false},"tocID":"editing_kms-d39307e15018","topics":[]},{"title":"Deleting KMS","shortdesc":"<p class=\"shortdesc\">Delete an AWS KMS key manager, Azure Key Vault, <span class=\"ph\">Google Cloud KMS             key manager, <\/span>or KMIP server when it is no longer needed and no particular KMS is         currently encrypting any data locations.<\/p>","href":"saas\/deleting_kms.html","attributes":{"data-id":"deleting_kms"},"menu":{"hasChildren":false},"tocID":"deleting_kms-d39307e15029","topics":[]},{"title":"Rekeying a data center archival location","shortdesc":"<p class=\"shortdesc\">Perform a rekey of the master key and\/or root key to update your encryption key to an         alternative encryption key. This ensures that your data location uses up-to-date         encryption.<\/p>","href":"saas\/rekeying_a_data_center_archival_location.html","attributes":{"data-id":"rekeying_a_data_center_archival_location"},"menu":{"hasChildren":false},"tocID":"rekeying_a_data_center_archival_location-d39307e15043","topics":[]},{"title":"Rekeying a cloud archival location","shortdesc":"<p class=\"shortdesc\">Rekey a client-side encrypted cloud archival location to replace the KMS key that         protects it, without re-encrypting the archived data.<\/p>","href":"saas\/rekeying_cnp_archival_location.html","attributes":{"data-id":"rekeying_cnp_archival_location"},"menu":{"hasChildren":false},"tocID":"rekeying_cnp_archival_location-d39307e15054","topics":[]},{"title":"Performing a rekey for Microsoft 365","shortdesc":"<p class=\"shortdesc\">Perform a rekey of the master key or intermediate key to update your encryption key         to an alternative encryption key. This ensures that your data location uses up-to-date         encryption.<\/p>","href":"saas\/m365_performing_rekey.html","attributes":{"data-id":"m365_performing_rekey"},"menu":{"hasChildren":false},"tocID":"m365_performing_rekey-d39307e15065","next":"m365_performing_rekey-d39307e15065"},{"title":"Updating the master key for a reader location","shortdesc":"<p class=\"shortdesc\">Update the master key to ensure data center reader locations can continue accessing         archived data after a rekey operation on the owner location.<\/p>","href":"saas\/updating_master_key.html","attributes":{"data-id":"updating_master_key"},"menu":{"hasChildren":false},"tocID":"updating_master_key-d39307e15087","topics":[]},{"title":"Rotating encryption keys","shortdesc":"<p class=\"shortdesc\">To provide enhanced encryption key security, you must rotate the encryption key or         switch to another root of trust for your encryption key. This functionality does not apply         to encryption keys for data center archival locations. <\/p>","href":"saas\/rotating_encryption_keys.html","attributes":{"data-id":"rotating_encryption_keys"},"menu":{"hasChildren":false},"tocID":"rotating_encryption_keys-d39307e15098","topics":[]}]}};